@layer components {
  [data-slot="badge"][data-tone="success"] {
    --badge-tone: var(--vh-success);
    --badge-tone-text: var(--vh-text-success, var(--vh-success));
  }

  [data-slot="badge"][data-tone="warning"] {
    --badge-tone: var(--vh-warning);
    --badge-tone-text: var(--vh-text-warning, var(--vh-warning));
  }

  [data-slot="badge"][data-tone="error"] {
    --badge-tone: var(--vh-error);
    --badge-tone-text: var(--vh-text-error, var(--vh-error));
  }

  [data-slot="badge"][data-tone="info"] {
    --badge-tone: var(--vh-info);
    --badge-tone-text: var(--vh-text-info, var(--vh-info));
  }

  /* Badge: a short label on a tinted fill with a 1px inner ring. */
  [data-slot="badge"] {
    --badge-fill: var(--vh-bg-muted);
    --badge-ring: var(--vh-border-accented);
    align-items: center;
    background: var(--badge-fill);
    border-radius: calc(var(--vh-radius) * 0.75);
    box-shadow: inset 0 0 0 1px var(--badge-ring);
    color: var(--vh-text);
    display: inline-flex;
    font-size: 0.75rem;
    font-weight: 500;
    gap: 0.25rem;
    line-height: 1rem;
    padding: 0.25rem 0.5rem;
    white-space: nowrap;
  }

  [data-slot="badge"][data-size="sm"] {
    border-radius: calc(var(--vh-radius) * 0.5);
    padding: 0.125rem 0.375rem;
  }

  [data-slot="badge"]:not([data-tone="neutral"]) {
    --badge-fill: color-mix(in oklab, var(--badge-tone) 10%, transparent);
    --badge-ring: color-mix(in oklab, var(--badge-tone) 25%, transparent);
    color: var(--badge-tone-text);
  }

  [data-slot="badge"][data-variant="outline"] {
    --badge-fill: transparent;
  }

  [data-slot="badge"][data-variant="solid"] {
    --badge-fill: var(--vh-highlighted);
    --badge-ring: transparent;
    color: var(--vh-inverted);
  }

  [data-slot="badge"][data-variant="solid"]:not([data-tone="neutral"]) {
    --badge-fill: var(--badge-tone);
    color: var(--vh-bg);
  }

  [data-slot="badge"] > svg {
    height: 0.75rem;
    width: 0.75rem;
  }
}

export type BadgeTone = "neutral" | "success" | "warning" | "error" | "info";
export type BadgeVariant = "soft" | "outline" | "solid";
export type BadgeSize = "sm" | "md";

export interface BadgeProps {
  tone?: BadgeTone;
  variant?: BadgeVariant;
  size?: BadgeSize;
  label?: string;
}

export interface BadgeSlots {
  default?: () => unknown;
  icon?: () => unknown;
}
